export const WORLD_W = 1000;
export const WORLD_H = 500.9;

const LAT_TOP = 84;
const K = 1000 / (2 * Math.PI);
const miller = (phi: number) => 1.25 * Math.log(Math.tan(Math.PI / 4 + 0.4 * phi));

/** Project lon/lat (degrees) into the map's 1000-wide coordinate space (Miller cylindrical). */
export function project(lon: number, lat: number): [number, number] {
    const x = ((lon + 180) / 360) * 1000;
    const y = (miller((LAT_TOP * Math.PI) / 180) - miller((lat * Math.PI) / 180)) * K;
    return [x, y];
}

export type Phase = 1 | 2 | 3 | 4;
export type WorldShape = readonly [key: string, phase: Phase, d: string];

